INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '预览技能压缩包','ai:skill:import:archive:api','api',p.id,'/v1/agent-console/skills/import/archive','POST','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:capability' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:skill:import:archive:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '预览GitHub技能','ai:skill:import:github:api','api',p.id,'/v1/agent-console/skills/import/github','POST','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:capability' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:skill:import:github:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '确认导入技能','ai:skill:import:commit:api','api',p.id,'/v1/agent-console/skills/import','POST','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:capability' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:skill:import:commit:api' AND del_flag=0);
INSERT INTO t_role_permission(role_id,permission_id,create_time,update_time,del_flag) SELECT r.id,p.id,NOW(),NOW(),0 FROM t_role r CROSS JOIN t_permission p WHERE r.code='superAdmin' AND r.status='active' AND r.del_flag=0 AND p.code IN ('ai:skill:import:archive:api','ai:skill:import:github:api','ai:skill:import:commit:api') AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_role_permission rp WHERE rp.role_id=r.id AND rp.permission_id=p.id AND rp.del_flag=0);
